import { headers } from 'next/headers'

type Analytics = { visitors: number; pageViews: number; bounceRate: number }
type Notification = { id: number; message: string; read: boolean }
type Settings = { theme: string; emailNotifications: boolean }

// Server-side fetch can't resolve relative paths, so build an absolute origin
// from the incoming request.
async function getBaseUrl() {
  const headerList = await headers()
  const host = headerList.get('host') ?? 'localhost:3000'
  const protocol =
    headerList.get('x-forwarded-proto') ??
    (host.startsWith('localhost') ? 'http' : 'https')

  return `${protocol}://${host}`
}

// Parallel data fetching: all three requests go out at once, so total latency is
// the slowest request rather than the sum of all three.
async function getDashboardData() {
  try {
    const baseUrl = await getBaseUrl()

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json() as Promise<Analytics>),
      fetch(`${baseUrl}/api/notifications`).then(
        (r) => r.json() as Promise<Notification[]>
      ),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json() as Promise<Settings>),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { visitors: 1000, pageViews: 4200, bounceRate: 0.32 },
      notifications: [{ id: 1, message: 'Notification 1', read: false }],
      settings: { theme: 'light', emailNotifications: true },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  const unread = notifications.filter((n) => !n.read).length

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Visitors: {analytics.visitors}</p>
        <p>Page views: {analytics.pageViews}</p>
        <p>Bounce rate: {Math.round(analytics.bounceRate * 100)}%</p>
      </section>

      <section>
        <h3>Notifications ({unread} unread)</h3>
        <ul>
          {notifications.map((notification) => (
            <li key={notification.id}>{notification.message}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>
          Email notifications: {settings.emailNotifications ? 'On' : 'Off'}
        </p>
      </section>
    </div>
  )
}

